parameters.jsCode:
// Verify the HMAC-SHA256 signature the Coastal site sends as x-coastal-signature.
//
// Requires the crypto builtin in the Code node. On your n8n instance set:
//   NODE_FUNCTION_ALLOW_BUILTIN=crypto
//
// The shared secret must match N8N_WEBHOOK_SECRET in the site's environment.
// Prefer the env var; the literal is only a fallback for quick testing.
const crypto = require('crypto');

const secret = $env.COASTAL_WEBHOOK_SECRET || 'REPLACE_WITH_N8N_WEBHOOK_SECRET';
const item = $input.first();

// rawBody puts the untouched request body in binary.data, base64 encoded.
const b64 = item.binary && item.binary.data ? item.binary.data.data : null;
const raw = b64
  ? Buffer.from(b64, 'base64').toString('utf8')
  : JSON.stringify(item.json.body || {});

const headers = item.json.headers || {};
const provided = headers['x-coastal-signature'] || '';
const expected = crypto.createHmac('sha256', secret).update(raw).digest('hex');

// Constant-time compare, so a wrong signature cannot be guessed byte by byte.
let valid = false;
try {
  const a = Buffer.from(expected, 'utf8');
  const b = Buffer.from(provided, 'utf8');
  valid = a.length === b.length && crypto.timingSafeEqual(a, b);
} catch (error) {
  valid = false;
}

let payload = {};
try {
  payload = JSON.parse(raw);
} catch (error) {
  valid = false;
}

return [
  {
    json: {
      valid,
      event: payload.event || null,
      leadId: payload.leadId || null,
      submittedAt: payload.submittedAt || null,
      lead: payload.lead || {},
    },
  },
];

